      else { stroke(md(H+22,360),lrp(4,70,dT/(DUR*0.45)),100,ca); strokeWeight(Math.max(0.4,u*0.0013*sc)); }
      line(cq[0],cq[1],cp[0],cp[1]);
    }
  }
}
